<?php require_once 'auth.php';requiereAdmin();$rows=$conexion->query('SELECT v.*,u.nombre cliente FROM ventas v JOIN usuario u ON u.idUsuario=v.idUsuario ORDER BY v.fecha DESC')->fetchAll();encabezado('Compras realizadas');?><div class="table-wrap"><table><tr><th>Folio</th><th>Cliente</th><th>Fecha</th><th>Total</th></tr><?php foreach($rows as $r):?><tr><td>#<?=e($r['idVenta'])?></td><td><?=e($r['cliente'])?></td><td><?=e($r['fecha'])?></td><td>$<?=number_format($r['total'],2)?></td></tr><?php endforeach;?></table></div><?php pie();?>